from _lib import *

CS6 = module("CS6", "Computing 6: data structures - lists, maps, stacks, and what each one costs", "Computing",
  "A list, a dictionary, a stack: these are not just Python words, they are shapes in memory, and each shape is fast at some things and slow at others. Knowing which shape to reach for is the difference between a program that answers in a blink and one that takes an hour. This is the first lesson in making code fast.",
  "Abid", "A program that takes the family's grocery list and Abid's budget and, in one pass, tells him what fits - using the right data structure, with a note on why she chose it.",
  [
    lesson("CS6-L1", "A list is boxes in a row: index, append, and the cost of each",
      ["Explain a list as contiguous numbered boxes in memory (back to CS1B-L0) and why index is instant", "Show that appending is usually cheap but inserting at the front is not, and explain why", "Use len, index, slice, append, insert and pop and say the cost of each in plain words"],
      FROM_ZERO + "A list is a row of boxes with addresses one after another - so box number 5 is found by arithmetic, instantly (that is why nums[5] is fast). Appending adds a box at the end (cheap). Inserting at the front shoves everyone up one (slow - she acts it out with five objects on the desk). Draw the row. HER HANDS in the editor: build a list, index it, slice it, append, insert at 0, pop. Then the cost words: instant (index), cheap (append), slow-when-big (insert/remove at front). Boundary Question: a list of a million items - which operations stay fast? Check: why nums[5] is instant."),
    lesson("CS6-L2", "A dictionary is a smart shelf: keys, hashing, and why lookup is instant",
      ["Explain a dictionary as key -> value and why finding by key is instant (hashing, back to DEF1-L3)", "Show when a dict beats a list (looking something up by name instead of searching)", "Use a dict to count things in one pass and explain the pattern"],
      FROM_ZERO + "A list finds by position; a dict finds by NAME. Mechanism: the key is hashed (the one-way scramble she met in DEF1) into a shelf number, so the value is found in one step, not by searching every item. That is why a phone book by name is a dict, not a list. Counting in one pass (she met this in CSTINY): for item in things: counts[item] = counts.get(item, 0) + 1. When a dict wins: 'have I seen this before?' on a million items - a list asks everyone, a dict asks once. Check: why a dict lookup is instant; one job a dict does better than a list."),
    lesson("CS6-L3", "Stacks and queues: last-in-first-out, first-in-first-out, and where they hide",
      ["Explain a stack (plates: last on, first off) and a queue (a line: first in, first out) with a picture", "Build each with a list and the right methods; explain the undo button and the browser's back button as stacks", "Connect the call stack (CS2A functions) to the plate stack - the same shape runs her programs"],
      FROM_ZERO + "A stack: plates - you take the top one; append and pop. A queue: a line at a shop - the front leaves first. Where they hide: Ctrl+Z undo is a stack of changes; the browser's Back is a stack of pages; a printer's jobs are a queue; the tutor's messages arrive in a queue. The big one: when her program calls a function that calls a function (CS2A), the computer keeps a STACK of where to return - the call stack; an error's 'traceback' is that stack printed. She builds both and explains undo. Check: stack vs queue, one real example of each."),
    code("CS6-CODE1", "Code: the right shape for the job",
      ["Solve the same task two ways (a list search vs a dict/set lookup) and time them", "Explain the difference in words, not just numbers", "Choose the shape for the gift (budget vs grocery list) and justify it"],
      "# Is each wanted item in the shop? Two ways.\nshop = [\"rice\", \"dal\", \"oil\", \"salt\", \"tea\", \"soap\"]\nwanted = [\"oil\", \"ghee\", \"tea\"]\n\n# way 1: search the list each time\nfor w in wanted:\n    found = False\n    for s in shop:\n        if s == w:\n            found = True\n    print(w, found)\n\n# way 2: a set - instant lookup\nshop_set = set(shop)\nfor w in wanted:\n    print(w, w in shop_set)\n",
      "Introduce set (a dict with keys only - instant 'is it in?'). Both give the same answer; the second asks once instead of searching. With a big shop the difference is huge - she reasons about it rather than timing a tiny one, then uses time.perf_counter on a list of 100,000 to see it for real. The gift: budget as the loop, a dict of prices for instant lookup. Save."),
    practice("CS6-P1", "Practice: which structure, and what it costs", ["list-operations-cost", "dict-lookup", "stack-queue", "choose-structure"]),
    lesson("CS6-H1", "Horizon: data structures are why the big things are fast",
      ["Explain how a search engine or a contacts app stays instant with billions of items (hashing, trees, indexes)", "Explain a database index as 'a dict the database keeps so it does not search every row' (tie to WEB1's SELECT)", "Ask: where would the wrong structure make a service too slow to use, and how would you fix it"],
      HORIZON + "The shapes she learned are the whole reason a phone finds a contact instantly among thousands and a search engine answers in a blink across billions. A database INDEX (WEB1) is exactly a dict the database keeps on the side so a SELECT does not read every row - the school's own tables have indexes (show one in lib/db.js's CREATE INDEX). Mechanism, not magic. Boundary Question: 'A site gets slow as it grows. Name one structure that was probably a list and should be a dict, and how you would tell.'"),
    check("CS6-C", "Computing 6 checkpoint", ["list-operations-cost", "dict-lookup", "stack-queue", "choose-structure"], count=10),
    teach("CS6-T", "Explain to a younger student the difference between a list and a dictionary using the shelf and the row picture, and say why finding a contact by name is instant. Say it out loud first, then write it. 4-6 sentences."),
  ])

M13 = module("M13", "Mathematics 13: logic and proof - true, false, and knowing for sure", "Mathematics",
  "A computer only ever asks one kind of question: true or false. Logic is the maths of those questions, and proof is how you become certain of something instead of just fairly sure. You already write logic every day in your if-statements; now you learn its rules, and how to show something must be true.",
  "Abid", "A logic puzzle she writes and solves for Abid (a 'who did it' with three clues), plus the Python that checks every possibility and confirms her answer.",
  [
    lesson("M13-L1", "And, or, not: the three gates, truth tables, and her if-statements",
      ["Build truth tables for and, or, not and read them", "Translate a sentence with 'and/or/not' into logic and evaluate it", "Connect to CS2A conditions and to the gates inside the computer (CS1 binary)"],
      FROM_ZERO + "Three operations run everything: AND (both true), OR (at least one), NOT (the opposite). Truth tables - she fills them in. 'You may play if homework is done AND it is not late': logic from a sentence. Tie back: her Python if age >= 13 and name == 'Faiza'; and forward: the computer is millions of these gates in silicon (CS1). Evaluate five compound conditions by hand, then check in Python (print(True and not False)). Check: the table for OR; translate one sentence."),
    practice("M13-P1", "Practice: logic and truth tables", ["truth-tables", "sentence-to-logic", "evaluate-conditions"]),
    lesson("M13-L2", "The traps: De Morgan, and why 'not (A and B)' surprises everyone",
      ["State De Morgan's laws and check them with truth tables", "Rewrite a negated condition correctly (the bug that hides in half of all code)", "Fix a deliberately wrong condition in a small program"],
      FROM_ZERO + "The most useful logic fact for a programmer: not (A and B) is (not A) or (not B) - the and flips to or. She proves it with a truth table (both columns match). Why it matters: 'stop unless the file exists AND is readable' negated wrong lets bad input through - a real security bug. She fixes a planted condition in a tiny program (an access check written wrong) and explains the fix. Boundary Question: write the condition for 'allow only if logged in and is the owner', then its correct negation. Check: De Morgan for 'not (A or B)'."),
    practice("M13-P2", "Practice: negation and De Morgan", ["de-morgan", "fix-condition", "negate-correctly"]),
    lesson("M13-L3", "Proof: from 'it works for these' to 'it must always work'",
      ["Explain the difference between an example and a proof, and why examples can fool you", "Prove two small things directly (the sum of two even numbers is even; a simple algebra identity)", "Meet proof by contradiction with one classic (there is no largest number)"],
      FROM_ZERO + "Testing shows a program works for the inputs she tried; proof shows it must work for all - the same gap as 'no bug found' vs 'no bug'. Direct proof: an even number is 2k; two of them sum to 2(k+m), which is even - done, for every even number at once. She proves one algebra identity. Contradiction: suppose there were a largest number N; then N+1 is larger - impossible, so there is none. The shape: assume the opposite, reach nonsense. Tie to security: a proof that a check cannot be bypassed beats a hundred tests. Check: why one example is not a proof."),
    code("M13-CODE1", "Code: let the computer check every case",
      ["Write a loop that checks a claim for every case in a range (a proof by exhaustion)", "Solve the gift's logic puzzle by trying all possibilities", "Explain when checking all cases is a real proof and when it is not"],
      "# Check a claim for every pair in a small range.\n# Claim: for 0..9, (a and b) is the same as not((not a) or (not b))\nfor a in [True, False]:\n    for b in [True, False]:\n        left = a and b\n        right = not ((not a) or (not b))\n        print(a, b, left == right)\n",
      "Every line prints True - a proof by exhaustion, because there are only four cases. Then the puzzle: three suspects, three clues; nested loops over who-did-it; print the one assignment that fits all clues (the gift). When exhaustion is a proof: only when the cases are finite and all checked - she says why she cannot prove the even-number fact this way (infinitely many). Save."),
    lesson("M13-H1", "Horizon: logic is the ground floor of maths, computers and law",
      ["Explain where formal logic shows up: circuits, program correctness, legal arguments, maths itself", "Explain in one line what it means that some true things cannot be proved (name Godel, do not go deep)", "Ask: where does a wrong 'and/or' cause real harm, and who checks for it"],
      HORIZON + "The same and/or/not is the silicon in her laptop, the conditions guarding a bank transfer, the structure of a legal argument (if the contract was signed AND not under duress...), and the foundation mathematicians built maths on. A famous limit, named lightly: in the 1930s Godel showed any rich enough system has true statements it cannot prove - certainty has an edge. Boundary Question: 'A payment is allowed if balance >= amount or overdraft is on. Write it, then the mistake that lets a payment through with no money, and who would catch it.'"),
    check("M13-C", "Mathematics 13 checkpoint", ["truth-tables", "sentence-to-logic", "de-morgan", "negate-correctly", "proof-basics"], count=12),
    teach("M13-T", "Explain to a younger student the difference between testing something and proving it, with one example of each. Then say what De Morgan's law is in your own words. Say it out loud first, then write it. 4-6 sentences."),
  ])

SS3 = module("SS3", "Systems & Society 3: law and courts - rules, rights, and how disputes end without a fight", "Systems & Society",
  "A law is a rule written down with force behind it. A court is the machine that decides, without violence, who is right when two people or a person and the state disagree. Understanding law is understanding the operating system that society runs on - its permissions, its checks, and where it can be gamed.",
  "Abid", "A plain-language 'how a dispute really gets settled' flowchart she draws for Abid, from disagreement to judgment to appeal, with the checks marked.",
  [
    lesson("SS3-L1", "What a law is: rule, force, and the kinds of law",
      ["Define a law and distinguish it from a custom or a company rule (force behind it)", "Name the main kinds (constitutional, criminal, civil, administrative) with one example each", "Explain where laws come from (legislature, SS1) and how one is changed"],
      FROM_ZERO + "A rule becomes law when the state will enforce it. Kinds: constitutional (the rules for the rules), criminal (state vs a person who broke a public rule), civil (person vs person over a wrong or a contract), administrative (the state's own agencies). One example each, from several countries. Tie to computing: laws are the system's permissions - who may do what, and the penalty for doing what you may not. Check: law vs custom; criminal vs civil."),
    lesson("SS3-L2", "The court machine: the two sides, the judge, the burden, and the standard",
      ["Explain the adversarial shape (two sides argue, a neutral decides) and why it is built that way", "Explain burden of proof and standard of proof (beyond reasonable doubt vs balance of probabilities) and why they differ for criminal and civil", "Trace a case from complaint to judgment"],
      FROM_ZERO + "Mechanism: not the judge investigating alone, but two sides each making their best case to a neutral - like adversarial testing of a program (LV5's spirit), the clash exposes weakness. Burden: who must prove (usually the accuser). Standard: how sure is enough - very sure to jail someone, more-likely-than-not for a money dispute - she says why the stakes set the bar. Trace a civil case: complaint, evidence, arguments, judgment. Check: who carries the burden; why the two standards differ."),
    lesson("SS3-L3", "Rights: what the state may not do to you, and how a right is enforced",
      ["Explain a right as a limit on power, not a gift, and name a few widely shared ones (fair trial, speech, privacy, property)", "Explain that a right is only real if a court will enforce it", "Connect privacy and property rights to her digital life (her data, her devices, DEF1)"],
      FROM_ZERO + "A right is a 'the state may not' - a permission denied to power itself (least privilege, one level up). Widely shared examples, framed as mechanism not politics: a fair hearing, speaking freely, not being searched without cause, owning things. The catch: a right on paper that no court enforces is a wish. Her digital version: who may read her messages, search her phone, own her data - the same questions, now legal as well as technical. Check: why a right is a limit, not a gift; what makes it real."),
    lesson("SS3-L4", "Contracts and the rules of the game online: terms, consent, and what she signs",
      ["Explain a contract as a promise the court will enforce and its parts (offer, acceptance, consideration)", "Read a real 'terms of service' and find three things she agreed to (data use, age, dispute rules)", "Explain why reading what you sign is a security habit, not just a legal one"],
      FROM_ZERO + "A contract is a deal with the court behind it. Parts, plainly. Then the real one: she opens the terms she already accepted (GitHub's or Proton's - the actual page) and finds three clauses - what they may do with her data, the age rule (she is 13, it matters), how disputes are handled. The habit: 'I agree' is a signature; reading it is the same reflex as 'read before you run' (CS3-L5). Check: the three parts of a contract; one thing she found in a real ToS."),
    lesson("SS3-H1", "Horizon: law meets the machine - crime, evidence and the cross-border problem",
      ["Explain how laws apply to computers (a crime is defined by law, not by what is technically possible) and why 'I only looked' is still a line", "Explain digital evidence and chain of custody as mechanism (why a log must be trustworthy - NET2, DEF1)", "Explain the cross-border problem: the attacker, the server and the victim in three countries"],
      HORIZON + "The ethics thread made legal: accessing a computer you are not authorised to is a crime in most countries regardless of how easy it was - which is why the school's rule (owned or invited systems only) is law as well as honour. Digital evidence: a log is evidence only if it can be shown to be unchanged - chain of custody, timestamps, hashes (DEF1) - a defender keeps logs partly for this. Cross-border: three countries, three laws, slow cooperation - why attackers hide across borders and why defence leans on prevention. Boundary Question: 'Your log is the evidence. What would make a court doubt it, and how do you prevent that?'"),
    check("SS3-C", "Systems & Society 3 checkpoint", ["kinds-of-law", "court-burden-standard", "rights-as-limits", "contracts-and-consent"], count=10),
    teach("SS3-T", "Explain to a 10-year-old how two people who disagree get it settled by a court instead of fighting, using the words sides, judge and proof. Then say why reading what you agree to online matters. Say it out loud first, then write it. 5-7 sentences."),
  ])

LV4 = module("LV4", "Leverage 4: read the system, not the instructions - speed and seeing the whole", "Leverage",
  "Beginners read every word and do what they are told. Experts glance, find the shape, and jump to the part that matters. This module trains the fast eye: skim a long thing for its structure, measure where your own time really goes, and automate the path you take most.",
  "Abid", "A 'time map' of her own week on the laptop (where the minutes went, measured not guessed) with the one thing she will automate, shown to Abid.",
  [
    lesson("LV4-L1", "Skim for structure: headings, signatures, and the 20% that holds the meaning",
      ["Skim a long documentation page in two minutes and say its shape (what it covers, where the part she needs is)", "Read code the fast way: names, function signatures, the shape before the detail", "Explain why understanding structure first makes the details land faster"],
      FROM_ZERO + "A long page has a skeleton: title, sections, examples. She practises on a real docs page - two minutes, then tells the tutor the shape and where her answer would be, before reading a single paragraph fully. Same for code: open one of her own longer programs and read only the function names and signatures first - the story of what it does appears before the lines. The principle (Pareto, named lightly): a small part carries most of the meaning; find it first. Check: the shape of a page she skimmed."),
    lesson("LV4-L2", "Measure, don't guess: where your time actually goes",
      ["Time three real tasks she does and compare to her guess", "Use the shell's time and Python's perf_counter to measure a program, not a feeling", "Explain why measuring beats guessing (the school's own minute-counting is an example)"],
      FROM_ZERO + LINUX + "People are terrible at guessing where time goes - the school itself learned this (the 20-vs-120-minute bug, the presence counter). She guesses how long three tasks take (the warm-up, writing a program, a Bandit level), then measures with a timer; the gap is the lesson. time ./report.sh; python3 -m timeit or perf_counter around a loop. The time map (gift): she notes her real minutes for a few days. Rule: optimise what you measured, not what you assume. Check: one task where her guess was wrong."),
    lesson("LV4-L3", "Automate the path you walk most: from three times to a script or an alias",
      ["Find the command sequence she types most and turn it into an alias or a script (CS3/CS4)", "Make three aliases in .bashrc and explain what .bashrc is", "Explain the rule of three again and the honest cost of automating too early"],
      FROM_ZERO + LINUX + "The lazy-programmer rule (LV1) grown to her whole workflow. She looks at her shell history (history | sort | uniq -c | sort -rn | head - the pipe from CS3) to find what she repeats, and turns the top one into an alias (alias gs='git status') or a short script. .bashrc explained (the terminal's settings, run at every open). The honest limit: automating a thing done once wastes more time than it saves - the rule of three decides. Check: what .bashrc is; one alias she made."),
    lesson("LV4-L4", "The fast path through a new tool: the five questions to ask anything",
      ["Apply five questions to a tool she has never used (what problem, how run, where help, what breaks, who made it) and get useful in ten minutes", "Do it live with one new small command-line tool", "Explain why this beats reading a whole manual first"],
      FROM_ZERO + LINUX + "A method for meeting anything new fast: (1) what problem does it solve? (2) how do I run the simplest thing? (3) where is help (--help, man, docs)? (4) what happens when I give it something wrong? (5) who made it and can I trust it (LV3)? She picks a small tool she has not used (the tutor suggests one safe CLI tool, e.g. jq or tree or ncdu) and gets genuinely useful with it in ten minutes using only the five questions. This is how she will meet every tool for the next ten years. Check: the five questions from memory."),
    check("LV4-C", "Leverage 4 checkpoint", ["skim-for-structure", "measure-not-guess", "automate-the-path", "five-questions"], count=8),
    teach("LV4-T", "Explain to Abid how you get useful with a brand-new tool in ten minutes, and how you decide what is worth automating. Say it out loud first, then write it. 4-6 sentences."),
  ])

MODULES = [CS6, M13, SS3, LV4]
